function html(body,title='Nook | Power, put to work',script=false,status=200){return new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="Nook is developing modular data centers at existing industrial sites with underused power. Explore your site's potential."><meta name="theme-color" content="#102d25"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="Modular data centers. Overlooked power. A new footprint for compute."><meta property="og:type" content="website"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css">${script?'<script src="/form.js" defer></script>':''}</head><body>${body}</body></html>`,{status,headers:{...securityHeaders,'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}});}
function header(active='home'){return `<a class="skip-link" href="#main">Skip to content</a><header class="header"><a class="wordmark" href="/" aria-label="Nook home">nook<span class="brand-mark" aria-hidden="true">▪</span></a><nav aria-label="Main navigation"><a href="/" ${active==='home'?'aria-current="page"':''}>Overview</a><a href="/submit-site" ${active==='submit'?'aria-current="page"':''}>Submit a site</a></nav><span class="header-descriptor">Power, put to work.</span></header>`;}
const footer=()=>`<footer class="footer wrap"><a class="wordmark" href="/" aria-label="Nook home">nook<span class="brand-mark" aria-hidden="true">▪</span></a><p>A new footprint for compute.</p><div><a href="/submit-site">Submit a site</a><a href="/privacy">Privacy</a><span>© ${new Date().getFullYear()} Nook</span></div></footer>`;
