 siteControl:['Owner','Operator / tenant','Developer','Broker / advisor','Utility / power partner','Other'],
 availablePower:['Under 500 kW','500 kW–1 MW','1–3 MW','3–5 MW','5–10 MW','More than 10 MW','Not sure yet'],
